select jsonb_build_object(
'tables',(select coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname,'rls',c.relrowsecurity,'owner',pg_get_userbyid(c.relowner)) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname in ('public','maat_private')),
'columns',(select coalesce(jsonb_agg(jsonb_build_object('name',table_schema||'.'||table_name||'.'||column_name,'type',udt_name,'nullable',is_nullable,'default',column_default) order by table_schema,table_name,ordinal_position),'[]') from information_schema.columns where table_schema in ('public','maat_private')),
'functions',(select coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')','definer',p.prosecdef,'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'definitionHash',md5(pg_get_functiondef(p.oid))) order by n.nspname,p.proname,p.oid),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind='f' and n.nspname in ('public','maat_private')),
'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',schemaname||'.'||tablename||'.'||policyname,'command',cmd,'roles',roles,'permissive',permissive,'using',qual,'check',with_check) order by schemaname,tablename,policyname),'[]') from pg_policies where schemaname in ('public','maat_private')),
'triggers',(select coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname||'.'||t.tgname,'definition',pg_get_triggerdef(t.oid)) order by n.nspname,c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','maat_private')),
'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname||'.'||x.conname,'definition',pg_get_constraintdef(x.oid)) order by n.nspname,c.relname,x.conname),'[]') from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','maat_private'))
,
'tableGrants',(select coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname||'|'||case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end||'|'||a.privilege_type,'grantable',a.is_grantable) order by n.nspname,c.relname,a.grantee,a.privilege_type),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where c.relkind='r' and n.nspname in ('public','maat_private')),
'columnGrants',(select coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname||'.'||t.attname||'|'||case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end||'|'||a.privilege_type,'grantable',a.is_grantable) order by n.nspname,c.relname,t.attname,a.grantee,a.privilege_type),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute t on t.attrelid=c.oid cross join lateral aclexplode(t.attacl) a where c.relkind='r' and n.nspname in ('public','maat_private')),
'functionGrants',(select coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')|'||case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end||'|'||a.privilege_type,'grantable',a.is_grantable) order by n.nspname,p.proname,p.oid,a.grantee,a.privilege_type),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.prokind='f' and n.nspname in ('public','maat_private')),
'indexes',(select coalesce(jsonb_agg(jsonb_build_object('name',schemaname||'.'||tablename||'.'||indexname,'definition',indexdef) order by schemaname,tablename,indexname),'[]') from pg_indexes where schemaname in ('public','maat_private'))
) as inventory;
